-- Judo Exam Requirements Database Schema
-- Judoclub Michigami Steenbergen
-- Generated by Kimi K2.6

CREATE TABLE belt_levels (id VARCHAR (50) PRIMARY KEY , name VARCHAR (100) NOT NULL , kyu INT , color VARCHAR (7) NOT NULL , color_name VARCHAR (50), is_slip BOOLEAN DEFAULT FALSE , parent_belt VARCHAR (50) REFERENCES belt_levels(id), sort_order INT NOT NULL);

-- Techniek-categorieën (ashi-waza, koshi-waza, etc.) CREATE TABLE technique_categories (id VARCHAR (50) PRIMARY KEY , parent_category VARCHAR (50), name_ja VARCHAR (100), name_nl VARCHAR (100), description TEXT);

-- Individuele technieken CREATE TABLE techniques (id VARCHAR (50) PRIMARY KEY , category_id VARCHAR (50) REFERENCES technique_categories(id), name_ja VARCHAR (100) NOT NULL , name_nl VARCHAR (100), is_forbidden BOOLEAN DEFAULT FALSE , list_order INT NOT NULL);

-- Vereiste aantallen per band per categorie CREATE TABLE belt_category_requirements (belt_id VARCHAR (50) REFERENCES belt_levels(id), category_id VARCHAR (50) REFERENCES technique_categories(id), required_count INT NOT NULL DEFAULT 0 , PRIMARY KEY (belt_id, category_id));

-- Algemene eisen per band (nage-komi, kanteltechnieken, ukemi) CREATE TABLE belt_general_requirements (belt_id VARCHAR (50) PRIMARY KEY REFERENCES belt_levels(id), nage_komi INT DEFAULT 0 , kantel_technieken INT DEFAULT 0 , ukemi_waza INT DEFAULT 4);

-- Expliciete koppeling: welke techniek wordt bij welke band geleerd CREATE TABLE belt_technique_assignments (belt_id VARCHAR (50) REFERENCES belt_levels(id), technique_id VARCHAR (50) REFERENCES techniques(id), PRIMARY KEY (belt_id, technique_id));

